version 2

# Example: Full RV32I but with restricted shift amounts
# Demonstrates sequential include/forbid operations

# Start with full RV32I instruction set
include RV32I

# Remove all shift instructions
forbid SLLI
forbid SRLI
forbid SRAI

# Add back only shifts with amount 0-7 (3-bit shifts)
include SLLI {shamt = 5'b00000}
include SLLI {shamt = 5'b00001}
include SLLI {shamt = 5'b00010}
include SLLI {shamt = 5'b00011}
include SLLI {shamt = 5'b00100}
include SLLI {shamt = 5'b00101}
include SLLI {shamt = 5'b00110}
include SLLI {shamt = 5'b00111}

include SRLI {shamt = 5'b00000}
include SRLI {shamt = 5'b00001}
include SRLI {shamt = 5'b00010}
include SRLI {shamt = 5'b00011}
include SRLI {shamt = 5'b00100}
include SRLI {shamt = 5'b00101}
include SRLI {shamt = 5'b00110}
include SRLI {shamt = 5'b00111}

include SRAI {shamt = 5'b00000}
include SRAI {shamt = 5'b00001}
include SRAI {shamt = 5'b00010}
include SRAI {shamt = 5'b00011}
include SRAI {shamt = 5'b00100}
include SRAI {shamt = 5'b00101}
include SRAI {shamt = 5'b00110}
include SRAI {shamt = 5'b00111}

# Result: Full RV32I with all shift instructions limited to 3-bit shift amounts (0-7)
# Upper 2 bits of shift amount are constrained to 00

instr_hit_latency 1
instr_miss_latency 5
data_hit_latency 1
data_miss_latency 4

PdatDsl/examples/bitpattern_addi_powers_.source_text:
# Example: Restrict ADDI immediate to powers of 2
# Demonstrates bit patterns for specific immediate values

require RV32I

# ADDI has a 12-bit signed immediate in bits [31:20]

# Allow only ADDI with immediate = 1 (0x001)
instruction ADDI { imm = 12'b000000000001 }

# Allow only ADDI with immediate = 2 (0x002)
instruction ADDI { imm = 12'b000000000010 }

# Allow only ADDI with immediate = 4 (0x004)
instruction ADDI { imm = 12'b000000000100 }

# Allow only ADDI with immediate = 8 (0x008)
instruction ADDI { imm = 12'b000000001000 }

# Result (in outlawing semantics): These specific values are forbidden
# All other immediate values are allowed

# For positive constraint (allow ONLY these), use:
# allow instruction ADDI { imm = 12'b000000000001 }
# allow instruction ADDI { imm = 12'b000000000010 }
# allow instruction ADDI { imm = 12'b000000000100 }
# allow instruction ADDI { imm = 12'b000000001000 }
# (Only powers of 2 from 1-8 would be allowed)

PdatDsl/examples/rv32im_narrow16.dsl.source_text:
# RV32IM with 16-bit maximum data width constraint
# This restricts ALL arithmetic instructions to operate only on 8-bit and 16-bit data types
# Useful for reducing hardware area by implementing only narrow multipliers/ALUs

# Require base instruction sets
require RV32I
require RV32M

# ============================================================================
# Data Type Constraint Strategy
# ============================================================================
# Using negated type sets to ALLOW ONLY narrow types (8-bit and 16-bit)
# This forbids 32-bit operations, enabling:
# - Smaller multiplier/divider units (16-bit instead of 32-bit)
# - Reduced ALU area
# - Synthesis optimization based on narrow operand assumptions
#
# Syntax: dtype = ~(i8 | u8 | i16 | u16)
# Meaning: Allow ONLY these types, forbid everything else (i32, u32, i64, u64)

# ============================================================================
# RV32M Instructions (Multiply/Divide)
# ============================================================================
# These are the primary targets for area reduction

instruction MUL    { dtype = ~(i8 | u8 | i16 | u16) }
instruction MULH   { dtype = ~(i8 | u8 | i16 | u16) }
instruction MULHSU { dtype = ~(i8 | u8 | i16 | u16) }
instruction MULHU  { dtype = ~(i8 | u8 | i16 | u16) }
instruction DIV    { dtype = ~(i8 | u8 | i16 | u16) }
instruction DIVU   { dtype = ~(i8 | u8 | i16 | u16) }
instruction REM    { dtype = ~(i8 | u8 | i16 | u16) }
instruction REMU   { dtype = ~(i8 | u8 | i16 | u16) }

# ============================================================================
# RV32I ALU Instructions (Register-Register)
# ============================================================================

instruction ADD  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SUB  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLL  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SRL  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SRA  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLT  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLTU { dtype = ~(i8 | u8 | i16 | u16) }
instruction XOR  { dtype = ~(i8 | u8 | i16 | u16) }
instruction OR   { dtype = ~(i8 | u8 | i16 | u16) }
instruction AND  { dtype = ~(i8 | u8 | i16 | u16) }

# ============================================================================
# RV32I ALU-Immediate Instructions
# ============================================================================

instruction ADDI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLTI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLTIU { dtype = ~(i8 | u8 | i16 | u16) }
instruction XORI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction ORI   { dtype = ~(i8 | u8 | i16 | u16) }
instruction ANDI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SLLI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SRLI  { dtype = ~(i8 | u8 | i16 | u16) }
instruction SRAI  { dtype = ~(i8 | u8 | i16 | u16) }

# ============================================================================
# Expected Hardware Benefits
# ============================================================================
# - Multiplier: 16x16 instead of 32x32 (approximately 4x area reduction)
# - Divider: 16-bit instead of 32-bit (significant area/timing improvement)
# - ALU: Can optimize assuming upper 16 bits are sign/zero extended
# - Register file: Upper bits may be optimized away in some paths
#
# For formal verification:
# - Reduced state space (operands bounded to 16 bits)
# - Faster convergence of proofs
# - Can prove properties about narrow arithmetic

PdatDsl/examples/rv32im_narrow8.dsl.source_text:
# RV32IM with 8-bit maximum data width constraint
# This restricts ALL arithmetic instructions to operate only on 8-bit data types
# Useful for minimal hardware implementations (8-bit microcontrollers, embedded systems)

# Require base instruction sets
require RV32I
require RV32M

# ============================================================================
# Data Type Constraint Strategy
# ============================================================================
# Using negated type sets to ALLOW ONLY 8-bit types
# This forbids 16-bit and 32-bit operations, enabling:
# - Minimal multiplier/divider units (8-bit only)
# - Smallest possible ALU area
# - Maximum synthesis optimization based on 8-bit operand assumptions
#
# Syntax: dtype = ~(i8 | u8)
# Meaning: Allow ONLY these types, forbid everything else (i16, u16, i32, u32, i64, u64)

# ============================================================================
# RV32M Instructions (Multiply/Divide)
# ============================================================================
# 8-bit multiplier: 8x8=16 bit result (vs 32x32=64 bit)
# Area reduction: approximately 16x smaller than 32-bit multiplier

instruction MUL    { dtype = ~(i8 | u8) }
instruction MULH   { dtype = ~(i8 | u8) }
instruction MULHSU { dtype = ~(i8 | u8) }
instruction MULHU  { dtype = ~(i8 | u8) }
instruction DIV    { dtype = ~(i8 | u8) }
instruction DIVU   { dtype = ~(i8 | u8) }
instruction REM    { dtype = ~(i8 | u8) }
instruction REMU   { dtype = ~(i8 | u8) }

# ============================================================================
# RV32I ALU Instructions (Register-Register)
# ============================================================================

instruction ADD  { dtype = ~(i8 | u8) }
instruction SUB  { dtype = ~(i8 | u8) }
instruction SLL  { dtype = ~(i8 | u8) }
instruction SRL  { dtype = ~(i8 | u8) }
instruction SRA  { dtype = ~(i8 | u8) }
instruction SLT  { dtype = ~(i8 | u8) }
instruction SLTU { dtype = ~(i8 | u8) }
instruction XOR  { dtype = ~(i8 | u8) }
instruction OR   { dtype = ~(i8 | u8) }
instruction AND  { dtype = ~(i8 | u8) }

# ============================================================================
# RV32I ALU-Immediate Instructions
# ============================================================================

instruction ADDI  { dtype = ~(i8 | u8) }
instruction SLTI  { dtype = ~(i8 | u8) }
instruction SLTIU { dtype = ~(i8 | u8) }
instruction XORI  { dtype = ~(i8 | u8) }
instruction ORI   { dtype = ~(i8 | u8) }
instruction ANDI  { dtype = ~(i8 | u8) }
instruction SLLI  { dtype = ~(i8 | u8) }
instruction SRLI  { dtype = ~(i8 | u8) }
instruction SRAI  { dtype = ~(i8 | u8) }

# ============================================================================
# Expected Hardware Benefits
# ============================================================================
# Compared to full 32-bit implementation:
# - Multiplier: 8x8 instead of 32x32 (approximately 16x area reduction)
# - Divider: 8-bit instead of 32-bit (major area/timing improvement)
# - ALU: Can optimize assuming upper 24 bits are sign/zero extended
# - Overall: Suitable for ultra-low-area embedded microcontrollers
#
# Compared to 16-bit configuration (rv32im_narrow16.dsl):
# - Multiplier: 8x8 instead of 16x16 (approximately 4x additional reduction)
# - Total area savings: ~60-70% vs narrow16, ~90-95% vs full 32-bit
#
# Use cases:
# - 8-bit sensor nodes
# - Minimal RISC-V implementations
# - Power-constrained embedded systems
# - Formal verification with minimal state space

